using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{public void Execute(ExecutionResult result){for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Unsaved scene");Directory.CreateDirectory("Validation/StructuralQA");var sc=EditorSceneManager.OpenScene("Assets/Scenes/Blackshire_SourceGrid.unity",OpenSceneMode.Single);var roots=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>PrefabUtility.GetPrefabInstanceStatus(t.gameObject)==PrefabInstanceStatus.MissingAsset).ToArray();var rows=roots.Select(t=>t.name+"|"+t.position.ToString("R")+"|"+t.childCount+"|"+PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)).ToArray();File.WriteAllLines("Validation/StructuralQA/probe.txt",rows);result.Log("Missing objects "+roots.Length);}}
